window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a0485d3bd509f407"]={"versions": [{"id": "FIG-a0485d3bd509f407", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus der AUTOSAR Software Component Template Spezifikation zur Darstellung von Metaklassen für Kompatibilitätsbetrachtungen. Das Diagramm spezifiziert die strukturellen Beziehungen zwischen Port-Schnittstellen (<code>SenderReceiv erInterface</code>, <code>ClientServ erInterface</code>), Prototypen (<code>DataElementPrototype</code>, <code>OperationPrototype</code>, <code>ArgumentPrototype</code>), dem abstrakten Datenträger <code>DataPrototype</code> sowie dem typisierenden Element <code>Datatype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>SenderReceiv erInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+dataElement</code> mit Multiplizität <code>0..*</code> Instanzen von <code>DataElementPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>ClientServ erInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+operation</code> mit Multiplizität <code>1..*</code> Instanzen von <code>OperationPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>OperationPrototype</strong> («atpStructureEleme...»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+argument</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> geordnete Instanzen von <code>ArgumentPrototype</code>.\n</li><li>Die Rückbeziehung besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>DataPrototype</strong> («atpPrototype», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse, von der <code>DataElementPrototype</code> («atpPrototype») und <code>ArgumentPrototype</code> über Generalisierung erben.\n</li><li>Besitzt eine gerichtete Assoziation <code>«isOfType»</code> zu <code>Datatype</code> («atpType», kursiv/abstrakt) mit Multiplizität <code>0..*</code> auf Seiten von <code>DataPrototype</code> und <code>+type 1</code> auf Seiten von <code>Datatype</code>.\n</li></ul>\n</li><li><strong>Datatype</strong> («atpType», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Typdefinition für Prototypen über die Relation <code>«isOfType»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Verhalten oder Nachrichtenaustausch dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen definieren das formale Typsystem für Kompatibilitätsprüfungen zwischen AUTOSAR-Software-Komponenten:</p>\n<ul class=\"fig-list\"><li>Schnittstellenkompatibilität bei Sender-Receiver-Kommunikation erfordert den Abgleich von <code>DataElementPrototype</code>-Elementen und deren typisierenden <code>Datatype</code>-Definitionen.\n</li><li>Bei Client-Server-Kommunikation müssen Operationen (<code>OperationPrototype</code>) in Anzahl, Namen und geordneter Argumentliste (<code>ArgumentPrototype</code> mit Eigenschaft <code>{ordered}</code>) sowie deren Typisierung (<code>Datatype</code>) übereinstimmen.\n</li><li>Beide Datenstrukturen (<code>DataElementPrototype</code> und <code>ArgumentPrototype</code>) teilen als Spezialisierungen von <code>DataPrototype</code> denselben Typisierungsmechanismus (<code>«isOfType»</code> auf <code>Datatype</code>), wodurch einheitliche Typprüfungsregeln zur Entwurfs- und Konfigurationszeit angewendet werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6a1487d9f0f88485", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus der AUTOSAR Software Component Template Spezifikation zur Darstellung von Metaklassen für Kompatibilitätsbetrachtungen. Das Diagramm spezifiziert die strukturellen Beziehungen zwischen Port-Schnittstellen (<code>SenderReceiv erInterface</code>, <code>ClientServerInterface</code>), Prototypen (<code>DataElementPrototype</code>, <code>OperationPrototype</code>, <code>ArgumentPrototype</code>), dem abstrakten Datenträger <code>DataPrototype</code> sowie dem typisierenden Element <code>Datatype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>SenderReceiv erInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+dataElement</code> mit Multiplizität <code>0..*</code> Instanzen von <code>DataElementPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>ClientServerInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+operation</code> mit Multiplizität <code>1..*</code> Instanzen von <code>OperationPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>OperationPrototype</strong> («atpStructureEleme...»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+argument</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> geordnete Instanzen von <code>ArgumentPrototype</code>.\n</li><li>Die Rückbeziehung besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>DataPrototype</strong> («atpPrototype», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse, von der <code>DataElementPrototype</code> («atpPrototype») und <code>ArgumentPrototype</code> über Generalisierung erben.\n</li><li>Besitzt eine gerichtete Assoziation <code>«isOfType»</code> zu <code>Datatype</code> («atpType», kursiv/abstrakt) mit Multiplizität <code>0..*</code> auf Seiten von <code>DataPrototype</code> und <code>+type 1</code> auf Seiten von <code>Datatype</code>.\n</li></ul>\n</li><li><strong>Datatype</strong> («atpType», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Typdefinition für Prototypen über die Relation <code>«isOfType»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Verhalten oder Nachrichtenaustausch dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen definieren das formale Typsystem für Kompatibilitätsprüfungen zwischen AUTOSAR-Software-Komponenten:</p>\n<ul class=\"fig-list\"><li>Schnittstellenkompatibilität bei Sender-Receiver-Kommunikation erfordert den Abgleich von <code>DataElementPrototype</code>-Elementen und deren typisierenden <code>Datatype</code>-Definitionen.\n</li><li>Bei Client-Server-Kommunikation müssen Operationen (<code>OperationPrototype</code>) in Anzahl, Namen und geordneter Argumentliste (<code>ArgumentPrototype</code> mit Eigenschaft <code>{ordered}</code>) sowie deren Typisierung (<code>Datatype</code>) übereinstimmen.\n</li><li>Beide Datenstrukturen (<code>DataElementPrototype</code> und <code>ArgumentPrototype</code>) teilen als Spezialisierungen von <code>DataPrototype</code> denselben Typisierungsmechanismus (<code>«isOfType»</code> auf <code>Datatype</code>), wodurch einheitliche Typprüfungsregeln zur Entwurfs- und Konfigurationszeit angewendet werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-73e04efc732becc4", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt aus der AUTOSAR Software Component Template Spezifikation zur Darstellung von Metaklassen für Kompatibilitätsbetrachtungen. Das Diagramm spezifiziert die strukturellen Beziehungen zwischen Port-Schnittstellen (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>), Prototypen (<code>DataElementPrototype</code>, <code>OperationPrototype</code>, <code>ArgumentPrototype</code>), dem abstrakten Datenträger <code>DataPrototype</code> sowie dem typisierenden Element <code>Datatype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Klassen, Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>SenderReceiverInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+dataElement</code> mit Multiplizität <code>0..*</code> Instanzen von <code>DataElementPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>ClientServerInterface</strong> («atpType»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+operation</code> mit Multiplizität <code>1..*</code> Instanzen von <code>OperationPrototype</code>.\n</li><li>Die Rückbeziehung <code>+interface</code> besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>OperationPrototype</strong> («atpStructureEleme...»):\n<ul class=\"fig-list\"><li>Besitzt über Komposition <code>+argument</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> geordnete Instanzen von <code>ArgumentPrototype</code>.\n</li><li>Die Rückbeziehung besitzt die Kardinalität <code>1</code>.\n</li></ul>\n</li><li><strong>DataPrototype</strong> («atpPrototype», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse, von der <code>DataElementPrototype</code> («atpPrototype») und <code>ArgumentPrototype</code> über Generalisierung erben.\n</li><li>Besitzt eine gerichtete Assoziation <code>«isOfType»</code> zu <code>Datatype</code> («atpType», kursiv/abstrakt) mit Multiplizität <code>0..*</code> auf Seiten von <code>DataPrototype</code> und <code>+type 1</code> auf Seiten von <code>Datatype</code>.\n</li></ul>\n</li><li><strong>Datatype</strong> («atpType», kursiv/abstrakt):\n<ul class=\"fig-list\"><li>Typdefinition für Prototypen über die Relation <code>«isOfType»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm des Metamodells; kein dynamisches Verhalten oder Nachrichtenaustausch dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Metaklassen definieren das formale Typsystem für Kompatibilitätsprüfungen zwischen AUTOSAR-Software-Komponenten:</p>\n<ul class=\"fig-list\"><li>Schnittstellenkompatibilität bei Sender-Receiver-Kommunikation erfordert den Abgleich von <code>DataElementPrototype</code>-Elementen und deren typisierenden <code>Datatype</code>-Definitionen.\n</li><li>Bei Client-Server-Kommunikation müssen Operationen (<code>OperationPrototype</code>) in Anzahl, Namen und geordneter Argumentliste (<code>ArgumentPrototype</code> mit Eigenschaft <code>{ordered}</code>) sowie deren Typisierung (<code>Datatype</code>) übereinstimmen.\n</li><li>Beide Datenstrukturen (<code>DataElementPrototype</code> und <code>ArgumentPrototype</code>) teilen als Spezialisierungen von <code>DataPrototype</code> denselben Typisierungsmechanismus (<code>«isOfType»</code> auf <code>Datatype</code>), wodurch einheitliche Typprüfungsregeln zur Entwurfs- und Konfigurationszeit angewendet werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a0485d3bd509f407", "to": "FIG-6a1487d9f0f88485", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>ClientServerInterface</strong>: Tippfehler im Klassennamen korrigiert (<code>ClientServ erInterface</code> zu <code>ClientServerInterface</code>).\n</li></ul>"}, {"from": "FIG-6a1487d9f0f88485", "to": "FIG-73e04efc732becc4", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>SenderReceiverInterface</strong>: Tippfehler im Klassennamen korrigiert (<code>SenderReceiv erInterface</code> zu <code>SenderReceiverInterface</code>).\n</li><li><strong>Kreuzung von Assoziationslinien</strong>: An der Kreuzung der Vererbungslinie von <code>DataElementPrototype</code>/<code>ArgumentPrototype</code> zu <code>DataPrototype</code> mit der Assoziationslinie <code>«isOfType»</code> wurde eine Leitungsbrücke (Bogen) eingefügt.\n</li></ul>"}]};
